import{_ as t,o,c as a,a3 as s}from"./chunks/framework.B3OtXxrP.js";const n="/blank/dev/screenshots/page-setup.png",u=JSON.parse('{"title":"Pages","description":"","frontmatter":{},"headers":[],"relativePath":"guide/pages.md","filePath":"guide/pages.md"}'),i={name:"guide/pages.md"};function r(d,e,p,h,c,l){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="pages" tabindex="-1">Pages <a class="header-anchor" href="#pages" aria-label="Permalink to &quot;Pages&quot;">​</a></h1><p>Your PDF and Word documents come out on the paper of your region, A4 or Letter, with generous margins of 2.5 cm. Most documents never need more than that. When one does, a single shortcut gets you there.</p><h2 id="page-setup" tabindex="-1">Page setup <a class="header-anchor" href="#page-setup" aria-label="Permalink to &quot;Page setup {#page-setup}&quot;">​</a></h2><p>Press <code>Mod</code> <code>Alt</code> <code>U</code>, or choose <strong>Page Setup…</strong> from the menu (right-click or <code>Shift</code> <code>F10</code>).</p><p><img src="'+n+`" alt="The page setup dialog with the paper, orientation and margins, and a picture of the page"></p><table tabindex="0"><thead><tr><th>Setting</th><th>Choices</th></tr></thead><tbody><tr><td>Paper</td><td>the paper of your region, A3, A4, A5, B5, Letter, Legal, or any size</td></tr><tr><td>Orientation</td><td>portrait or landscape</td></tr><tr><td>Margins</td><td>narrow (1.27 cm), normal (2.5 cm), wide (3.5 cm), or your own</td></tr></tbody></table><p>Everything works from the keyboard: <code>↑</code> <code>↓</code> move between the settings, <code>←</code> <code>→</code> change one, <code>Enter</code> applies and <code>Esc</code> leaves everything as it was. The picture of the page follows every change, so you see what you get before you apply it.</p><p>For your own size or margins, choose <strong>Custom…</strong> and type them below. Numbers are in centimetres, or in inches where Letter paper is used, and you can also write the unit, like <code>25mm</code> or <code>1in</code>.</p><p>Changed your mind? <code>Mod</code> <code>Z</code> undoes the whole page setup at once.</p><h2 id="frontmatter" tabindex="-1">Where the page setup is kept <a class="header-anchor" href="#frontmatter" aria-label="Permalink to &quot;Where the page setup is kept {#frontmatter}&quot;">​</a></h2><p>The page setup belongs to the document, so it prints the same on every computer. Blank writes it into the <a href="./files#frontmatter">properties at the top of the file</a>, and only what differs from your defaults:</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">page:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  size: a5</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  orientation: landscape</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  margins: 2cm</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span></code></pre></div><p>You can write these yourself too. <code>size</code> is <code>a3</code>, <code>a4</code>, <code>a5</code>, <code>b5</code>, <code>letter</code>, <code>legal</code>, <code>auto</code> for the paper of your region, or a size like <code>170mm x 240mm</code>. <code>margins</code> is one length for all four sides, or <code>top</code>, <code>right</code>, <code>bottom</code> and <code>left</code> on their own lines. Lengths are written with their unit: <code>mm</code>, <code>cm</code>, <code>in</code> or <code>pt</code>.</p><p>The line above your text sums the page setup up, for example <em>A5 landscape · margins 2 cm</em>. Click it to open the page setup. <strong>Edit as Text</strong> in the dialog shows all properties of the file, to change the ones the dialog has no settings for.</p><p>If a setting can&#39;t be used, say a paper size Blank doesn&#39;t know, the export uses your default for it and tells you so.</p><h2 id="defaults" tabindex="-1">Your defaults <a class="header-anchor" href="#defaults" aria-label="Permalink to &quot;Your defaults {#defaults}&quot;">​</a></h2><p><strong>Make This My Default</strong> in the page setup keeps the settings for every document that doesn&#39;t have its own. Blank saves them in <a href="./configuration#page-setup"><code>blank.json</code></a>.</p><h2 id="word" tabindex="-1">Page setup and Word <a class="header-anchor" href="#word" aria-label="Permalink to &quot;Page setup and Word {#word}&quot;">​</a></h2><p>Word documents keep their page setup both ways: an export to Word has your paper, orientation and margins, and a Word document you open brings along its own. If someone changed the page setup in Word, you get their version.</p><p>Word can do a few things Blank&#39;s page setup can&#39;t hold. When a document has them, Blank tells you right after opening it:</p><ul><li>sections with different page setups: Blank uses the first one,</li><li>a binding margin, which is left out,</li><li>mirrored margins for printing both sides, which become the same on every page.</li></ul>`,21)])])}const m=t(i,[["render",r]]);export{u as __pageData,m as default};
